(window.__AC=window.__AC||{});__AC["assets"]=(__AC["assets"]||'')+"window.ASSETS_LINES={\"i1\":{\"s\":\"narr\",\"t\":\"Хальда всегда смотрит на своё солнце одной стороной. Там, где вечный полдень, плавится камень. Там, где вечная ночь, замерзает сам воздух.\"},\"i2\":{\"s\":\"narr\",\"t\":\"Девятьсот лет назад сюда упал корабль. Колонисты выжили. Но со временем забыли, откуда пришли.\"},\"i3\":{\"s\":\"narr\",\"t\":\"Жить можно только в сумерках, на узкой Линии Зари. Но она ползёт. Поэтому мы построили города на колёсах. И никогда не останавливаемся.\"},\"i4\":{\"s\":\"irma\",\"t\":\"Отстал на день — замёрз. Обогнал на день — сгорел. Мы живём ровно посередине. И это называется дом.\"},\"i5\":{\"s\":\"narr\",\"t\":\"Три дня назад солнечная вспышка разорвала путь впереди города Орсо. Город встал. И его хвост начал плавиться.\"},\"i6\":{\"s\":\"irma\",\"t\":\"Меня зовут Ирма Кесс. Я путевая обходчица. Моя работа — чтобы у города была дорога. Даже когда её нет.\"},\"r_start\":{\"s\":\"avram\",\"t\":\"Ирма, приём! Хвост горит. Совет решил ползти к разрыву — стоять больше нельзя. Пробирайся к голове состава и почини путь, пока мы не дошли до края.\"},\"r_start2\":{\"s\":\"irma\",\"t\":\"Поняла, дед Аврам. Иду.\"},\"r_heat\":{\"s\":\"avram\",\"t\":\"Осторожно со светом. Солнце в щелях жжёт насквозь. Держись тени и следи за костюмом.\"},\"r_vent\":{\"s\":\"irma\",\"t\":\"Клапаны травят пар. Надо ловить момент.\"},\"r_grapple\":{\"s\":\"irma\",\"t\":\"Сцепку оборвало. Ну, Клюв, не подведи.\"},\"r_pechka\":{\"s\":\"avram\",\"t\":\"Твоя Печка копит жар на свету. Им можно сделать рывок. А впереди он ещё и согреет.\"},\"r_chase\":{\"s\":\"avram\",\"t\":\"Ирма! Перегрев идёт волной, вагоны рушатся прямо за тобой! Беги! Не оглядывайся!\"},\"r_chase_end\":{\"s\":\"irma\",\"t\":\"Проскочила. Дед, я на крышах головных вагонов.\"},\"r_cold\":{\"s\":\"avram\",\"t\":\"Впереди тень. Холод там злой. Грейся от Печки и от жаровен. И не стой на месте.\"},\"r_sentinel\":{\"s\":\"avram\",\"t\":\"Вижу фонарщиков Гильдии. Странно. Что им делать у нашего города? Не попадайся в их луч — он жжёт не хуже солнца.\"},\"r_end\":{\"s\":\"irma\",\"t\":\"Вот он, разрыв. Сейчас. Сейчас поставлю.\"},\"e1\":{\"s\":\"avram\",\"t\":\"Ирма... Я перехватил приказ Гильдии. Орсо исключён из Кольцевого пути. Ремонт не планируется. Нас решили бросить.\"},\"e2\":{\"s\":\"irma\",\"t\":\"Значит, дорогу мы проложим сами. Через полдень. Через ночь. Куда угодно.\"},\"e3\":{\"s\":\"narr\",\"t\":\"Так начинается путь Ирмы Кесс. Продолжение следует.\"},\"d1\":{\"s\":\"irma\",\"t\":\"Ещё раз.\"},\"d2\":{\"s\":\"irma\",\"t\":\"Не сейчас. Не так.\"}};\nwindow.ASSETS_AUDIO={\"m_chase\":\"";